import math

def check_divisibility(n):
    if n < 0:
        return False

    numerator = 3 * (math.factorial(n + 2) + 1)
    denominator = 2 * n - 1

    if denominator == 0:
        # Should not happen for n >= 0 as 2n-1 >= -1
        return False

    # Handle n=0 case where denominator is -1
    if denominator < 0:
        if numerator % abs(denominator) == 0:
            return True
        else:
            return False

    return numerator % denominator == 0

