import math

def check_integer(n):
    if n < 0:
        return False

    denominator = 2 * n - 1

    # Handle division by zero, although for n >= 0, 2n-1 != 0.
    if denominator == 0:
        return False

    # Calculate numerator: 3 * ((n+2)! + 1)
    try:
        fact = math.factorial(n + 2)
        numerator = 3 * (fact + 1)
    except OverflowError:
        # Should not happen for small N, but good practice.
        return False

    # Check divisibility
    return numerator % denominator == 0

